package edu.portal.web;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api") public class ApiController { private final JdbcPortalRepository repo; public ApiController(JdbcPortalRepository r){repo=r;} @GetMapping("/students") List<Map<String,Object>> students(@RequestParam(defaultValue="")String q){return repo.students(q);}@GetMapping("/vacancies") List<Map<String,Object>> vacancies(){return repo.vacancies();}@GetMapping("/applications") List<Map<String,Object>> applications(@RequestParam(defaultValue="")String status){return repo.applications(status);}@GetMapping("/reports/{name}") List<Map<String,Object>> reports(@PathVariable String name){return repo.report(view(name));}@GetMapping(value="/reports/{name}.csv",produces="text/csv") ResponseEntity<String> csv(@PathVariable String name){var rows=repo.report(view(name));if(rows.isEmpty())return ResponseEntity.ok("");var keys=new ArrayList<>(rows.get(0).keySet());String body=String.join(",",keys)+"\n"+rows.stream().map(r->keys.stream().map(k->"\""+String.valueOf(r.get(k)).replace("\"","\"\"")+"\"").collect(Collectors.joining(","))).collect(Collectors.joining("\n"));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+name+".csv").body(body);} private String view(String n){return switch(n){case "companies"->"v_company_recruitment_summary";case "departments"->"v_department_placement_stats";default->"v_vacancy_application_counts";};} }
